// Ensure payload is an object
let payload = msg.payload;
if (typeof payload === 'string') {
    try {
        payload = JSON.parse(payload);
    } catch (e) {
        node.error('Malformed JSON from MQTT: ' + msg.payload, msg);
        return null;
    }
}

if (!payload || typeof payload !== 'object') {
    node.error('Invalid status payload structure: expected object', msg);
    return null;
}

// Reject any prohibited temperature fields
for (let k in payload) {
    let lower = k.toLowerCase();
    if (lower.includes('temp') || lower.includes('thermal')) {
        node.error('Strict Zero-Temperature Policy Violation: Field ' + k + ' rejected', msg);
        return null;
    }
}

if (!payload.device || !payload.status) {
    node.error('Missing required status fields (device, status)', msg);
    return null;
}

// Construct clean payload - strictly zero-temperature compliance
let cleanPayload = {
    device: String(payload.device),
    status: String(payload.status)
};

if (payload.timestamp) {
    cleanPayload.timestamp = payload.timestamp;
}
if (payload.uptime !== undefined && payload.uptime !== null) {
    cleanPayload.uptime = Number(payload.uptime);
}
if (payload.rssi !== undefined && payload.rssi !== null) {
    cleanPayload.rssi = Number(payload.rssi);
}

msg.headers = {
    'Content-Type': 'application/json'
};
msg.payload = cleanPayload;
return msg;

let code = msg.statusCode;
if (code === 200) {
    node.status({ fill: 'green', shape: 'dot', text: 'HTTP 200 ACK' });
    return [msg, null];
} else {
    node.status({ fill: 'red', shape: 'ring', text: 'HTTP ' + code });
    return [null, msg];
}

