        node.error('Strict Zero-Temperature Policy Violation: Prohibited field "' + k + '" detected', msg);
        return null;
    }
}

// Construct clean payload ONLY with explicitly supplied actual values.
// STRICT: NO FALLBACK OR FABRICATED VALUES (voltage || 230, etc. FORBIDDEN).
let clean = {};

if (payload.timestamp !== undefined && payload.timestamp !== null) {
    clean.timestamp = payload.timestamp;
}
if (payload.voltage !== undefined && payload.voltage !== null) {
    clean.voltage = Number(payload.voltage);
}
if (payload.current !== undefined && payload.current !== null) {
    clean.current = Number(payload.current);
}
if (payload.power !== undefined && payload.power !== null) {
    clean.power = Number(payload.power);
}
if (payload.energy !== undefined && payload.energy !== null) {
    clean.energy = Number(payload.energy);
}
if (payload.frequency !== undefined && payload.frequency !== null) {
    clean.frequency = Number(payload.frequency);
}
if (payload.power_factor !== undefined && payload.power_factor !== null) {
    clean.power_factor = Number(payload.power_factor);
}
if (payload.data_source !== undefined && payload.data_source !== null) {
    clean.data_source = String(payload.data_source);
}

msg.headers = {
    'Content-Type': 'application/json'
};
msg.payload = clean;
return msg;

let code = msg.statusCode;
