let payload = msg.payload;
if (typeof payload === 'string') {
    try {
        payload = JSON.parse(payload);
    } catch (e) {
        node.error('Malformed JSON from MQTT channel: ' + msg.payload, msg);
        return null;
    }
}

if (!payload || typeof payload !== 'object') {
    node.error('Invalid channel payload structure: expected object', msg);
    return null;
}

// STRICT ZERO-TEMPERATURE POLICY: Reject prohibited fields immediately
for (let k in payload) {
    let lower = k.toLowerCase();
    if (lower.includes('temp') || lower.includes('thermal')) {
        node.error('Strict Zero-Temperature Policy Violation: Prohibited field "' + k + '" detected', msg);
        return null;
    }
}

// Extract and validate channel index: must be strictly 1, 2, 3, or 4
let rawCh = payload.channel;
if (rawCh === undefined || rawCh === null) {
    // Try parsing from topic smarttransformer/channel/<id>
    if (typeof msg.topic === 'string') {
        let parts = msg.topic.split('/');
        rawCh = parts[parts.length - 1];
    }
}

let channelNum = Number(rawCh);
if (!Number.isInteger(channelNum) || channelNum < 1 || channelNum > 4) {
    node.error('Invalid channel rejected: ' + rawCh + ' (only 1, 2, 3, 4 permitted)', msg);
    return null;
}

// Construct clean payload - ONLY supplied values, no fake fallbacks
let clean = {
    channel: channelNum
};

if (payload.timestamp !== undefined && payload.timestamp !== null) {
    clean.timestamp = payload.timestamp;
}

// Electrical metrics: Voltage and Current
let v = (payload.voltage !== undefined && payload.voltage !== null) ? Number(payload.voltage) : null;
let i = (payload.current !== undefined && payload.current !== null) ? Number(payload.current) : null;

if (v !== null) clean.voltage = v;
if (i !== null) clean.current = i;

// Apparent Power (VA) calculation:
// If both voltage and current exist: apparent_power = voltage * current (VA)
// If voltage or current is missing: apparent_power must remain null / omitted
if (v !== null && i !== null) {
    clean.apparent_power = Math.round(v * i * 10) / 10;
} else if (payload.apparent_power !== undefined && payload.apparent_power !== null) {
    clean.apparent_power = Number(payload.apparent_power);
}

// Relays and load states
if (payload.main_relay !== undefined && payload.main_relay !== null) {
    clean.main_relay = Boolean(payload.main_relay);
}
if (payload.aux_relay !== undefined && payload.aux_relay !== null) {
    clean.aux_relay = Boolean(payload.aux_relay);
}
if (payload.load !== undefined && payload.load !== null) {
    clean.load = Boolean(payload.load);
}
if (payload.load_active !== undefined && payload.load_active !== null) {
    clean.load_active = Boolean(payload.load_active);
}
if (payload.status !== undefined && payload.status !== null) {
    clean.status = String(payload.status);
}
if (payload.fault !== undefined && payload.fault !== null) {
    clean.fault = String(payload.fault);
}
if (payload.data_source !== undefined && payload.data_source !== null) {
    clean.data_source = String(payload.data_source);
}

msg.headers = {
    'Content-Type': 'application/json'
};
msg.payload = clean;
return msg;

let code = msg.statusCode;
if (code === 200) {
    node.status({ fill: 'green', shape: 'dot', text: 'HTTP 200 ACK' });
    return [msg, null];
} else {
    node.status({ fill: 'red', shape: 'ring', text: 'HTTP ' + code });
    return [null, msg];
}
